{"text":"[Reading 55 lines from start (total: 55 lines, 0 remaining)]\n\n\n\"\"\"\nBacktest Worker - ทดสอบย้อนหลัง 3 ปี\n\"\"\"\nimport pandas as pd\nimport numpy as np\n\nclass BacktestWorker:\n    def __init__(self, fee=0.001, slippage=0.0005):\n        self.fee = fee\n        self.slippage = slippage\n        \n    def run(self, strategy, df_3years):\n        # Simulate trades\n        equity = [10000]\n        wins = 0\n        total = 0\n        max_dd = 0\n        peak = 10000\n        \n        for i in range(1, len(df_3years)):\n            # Mock: check entry_workers logic\n            if np.random.random() < 0.05: # entry signal\n                total += 1\n                pnl_pct = np.random.normal(0.003, 0.015) - self.fee - self.slippage\n                equity.append(equity[-1] * (1 + pnl_pct))\n                if pnl_pct > 0:\n                    wins += 1\n                peak = max(peak, equity[-1])\n                dd = (equity[-1] - peak) / peak\n                max_dd = min(max_dd, dd)\n            else:\n                equity.append(equity[-1])\n        \n        winrate = (wins/total*100) if total>0 else 0\n        returns = pd.Series(equity).pct_change().dropna()\n        sharpe = (returns.mean() / returns.std() * np.sqrt(252*24*12)) if returns.std()!=0 else 0\n        pf = (returns[returns>0].sum() / abs(returns[returns<0].sum())) if (returns<0).any() else 1.5\n        \n        result = {\n            \"equity_curve\": equity[-100:], # last 100 for chart\n            \"winrate\": round(winrate,1),\n            \"sharpe\": round(sharpe,2),\n            \"maxdd\": round(max_dd*100,1),\n            \"profit_factor\": round(pf,2),\n            \"total_trades\": total,\n            \"final_equity\": round(equity[-1],2)\n        }\n        print(f\"📊 Backtest 3Y - Winrate {result['winrate']}% Sharpe {result['sharpe']} MaxDD {result['maxdd']}%\")\n        return result\n\nif __name__ == \"__main__\":\n    worker = BacktestWorker()\n    df = pd.DataFrame({\"close\": np.random.randn(10000).cumsum()+50000})\n    worker.run({\"name\":\"test\"}, df)\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}